// Розбір заявок «GA | Leaver» (трекер 41): AD-логін, дата звільнення, гостьова пошта Google.
// Вихід: action = 'process' (готово до обробки) або 'notify' (у заявці бракує даних, треба коментар).
// Коментар про ту саму проблему пишеться один раз (пам'ять у static data флоу).
const TRACKER_ID = 41;
const LOGIN_CF_ID = 87;      // кастомне поле «AD login»
const TERM_DATE_CF_ID = 30;  // кастомне поле «Termination date»
const LOGIN_RE = /^[A-Za-z0-9][A-Za-z0-9._-]*(@[A-Za-z0-9.-]+\.[A-Za-z]{2,})?$/;

const state = $getWorkflowStaticData('global');
state.notified_input = state.notified_input || {};
state.notified_run = state.notified_run || {};

const today = DateTime.now().setZone('Europe/Kyiv').toISODate();
// Доступ до Google API працює? Тоді 403 на конкретного гостя означає «гостя немає» (див. final_report.js).
const hc = $('[Google] Check API Access').first().json;
const gw_ok = Number(hc.statusCode) === 200;

let issues = [];
for (const it of $input.all()) {
  if (Array.isArray(it.json.issues)) issues.push(...it.json.issues);
  else if (it.json && it.json.id) issues.push(it.json);
}

const cf = (issue, id, name) => (issue.custom_fields || []).find(f => f.id === id || f.name === name);

// Транслітерація за постановою КМУ №55 (2010), як імена записані в AD (Зразковий Олег -> Zrazkovyi Oleh).
const TR = { а:'a', б:'b', в:'v', г:'h', ґ:'g', д:'d', е:'e', є:'ie', ж:'zh', з:'z', и:'y', і:'i', ї:'i', й:'i', к:'k', л:'l',
  м:'m', н:'n', о:'o', п:'p', р:'r', с:'s', т:'t', у:'u', ф:'f', х:'kh', ц:'ts', ч:'ch', ш:'sh', щ:'shch', ь:'', ю:'iu', я:'ia',
  ы:'y', э:'e', ё:'io', ъ:'' };
const TR_START = { є:'ye', ї:'yi', й:'y', ю:'yu', я:'ya', ё:'yo' };
function translit(word) {
  const w = word.toLowerCase().replace(/[’'ʼ`]/g, '').replace(/зг/g, 'zgh');
  let out = '';
  for (let i = 0; i < w.length; i++) {
    const c = w[i];
    out += (i === 0 && TR_START[c]) || (TR[c] !== undefined ? TR[c] : c);
  }
  return out.charAt(0).toUpperCase() + out.slice(1);
}
// Шаблони логінів в AD (запасний пошук, якщо в акаунта не заповнені ім'я/прізвище):
// ім'я.прізвище, і.прізвище, ms.і.прізвище, ms.ім'я.прізвище (ms. у старих акаунтів).
const loginVariants = (g, s) => {
  const G = g.toLowerCase().replace(/[^a-z-]/g, ''), S = s.toLowerCase().replace(/[^a-z-]/g, '');
  if (!G || !S) return [];
  return [`${G}.${S}`, `${G[0]}.${S}`, `ms.${G[0]}.${S}`, `ms.${G}.${S}`];
};
// Значення для шаблону фільтра в LDAP-ноді: фіксовані слоти, зайві = NONE (нічого не знаходить).
// Нода сама екранує підставлені в шаблон значення (після оновлення n8n фільтр цілком з виразу ламається),
// тому тут лише прибираємо службові символи.
const NONE = '__none__';
const ldapClean = s => String(s).replace(/[\\*()\0]/g, '');
function slots(values, n) {
  const u = [...new Set(values.map(ldapClean).filter(Boolean))];
  if (u.length > n) throw new Error('Забагато значень для фільтра AD, ' + u.length + ' з ' + n);
  return u.concat(Array(n - u.length).fill(NONE));
}

// Прізвище й ім'я з рядка «ГА - ...» або теми. Повертає пари [ім'я, прізвище] у порядку правдоподібності:
// кирилиця «Прізвище Ім'я [По батькові]» -> транслітерація; латиниця «Ім'я [Друге] Прізвище» (регістр байдужий).
// Для імен із трьох і більше латинських слів додатково пробуємо «перше + останнє» (в AD часто без середнього імені).
const titleCase = w => w.charAt(0).toUpperCase() + w.slice(1).toLowerCase();
function parseName(issue) {
  const m = (issue.description || '').match(/(?:^|[\s|])ГА[ \t]*[-–—:][ \t]*([^\r\n]*)/);
  const fio = ((m && m[1]) || (issue.subject || '').split('|')[2] || '').trim().replace(/^(ФОП|ФЛП)\s+/i, '');
  const words = fio.split(/\s+/).filter(Boolean);
  if (words.length < 2) return null;
  let pairs;
  if (words.every(w => /^[А-Яа-яЁёЄєІіЇїҐґ’'ʼ-]+$/.test(w))) {
    const [sn, gn] = [translit(words[0]), translit(words[1])];
    pairs = [[gn, sn], [sn, gn]];
  } else if (words.every(w => /^[A-Za-z][A-Za-z’'ʼ.-]*$/.test(w))) {
    const n = words.map(titleCase), first = n[0], last = n[n.length - 1];
    pairs = n.length >= 3 ? [[first, last], [last, first], [first, n[1]], [n[1], first]] : [[first, last], [last, first]];
  } else return null;
  return { fio, pairs, gn: pairs[0][0], sn: pairs[0][1] };
}

// «Загалом днів співпраці: 24» із шаблону заявки (потрібно для перевірки акаунта за датою створення).
function tenureOf(issue) {
  const m = (issue.description || '').match(/співпраці[ \t]*:[ \t]*(\d+)/i);
  return m ? Number(m[1]) : null;
}

function parseLogin(issue) {
  // Рядок «AD - login» в описі. [ \t]* замість \s*, щоб не перескочити на наступний рядок.
  const m = (issue.description || '').match(/(?:^|[\s|])AD[ \t]*[-–—:][ \t]*([^\r\n]*)/i);
  let raw = m ? m[1].trim() : '';
  if (!raw) {
    const f = cf(issue, LOGIN_CF_ID, 'AD login');
    raw = f && f.value ? String(f.value).trim() : '';
  }
  if (!raw) return { reason: 'no_login' };
  const login = raw.split(/\s+/)[0];
  if (!LOGIN_RE.test(login)) return { reason: 'bad_login', value: raw };
  return { login };
}

function parseDate(issue) {
  const f = cf(issue, TERM_DATE_CF_ID, 'Termination date');
  let d = (f && f.value) || issue.due_date || ((issue.subject || '').match(/(\d{4}-\d{2}-\d{2})/) || [])[1] || '';
  d = String(d).trim();
  if (!d) return { reason: 'no_date' };
  if (!/^\d{4}-\d{2}-\d{2}$/.test(d) || !DateTime.fromISO(d).isValid) return { reason: 'bad_date', value: d };
  return { date: d };
}

// [що перевірено, результат, що робити далі]
const NOTES = {
  no_login: () => ['• Рядок «AD -» в описі: порожній.\n• Поле «AD login»: порожнє.\n• ПІБ (рядок «ГА -» або тема заявки): не знайдено, тому пошук в AD за ПІБ неможливий.',
    'AD-логін не вказано, і знайти працівника в AD немає за чим.',
    ['впишіть логін у рядок «AD -» (або ПІБ у рядок «ГА -»), і автоматизація обробить заявку сама;',
     'якщо акаунта в AD немає, перевірте гостьовий акаунт Google і закрийте заявку вручну.']],
  bad_login: v => [`• Рядок «AD -» в описі: «${v}».`,
    `AD-логін «${v}» має неприпустимий формат (очікується латиниця без пробілів, наприклад ivan.petrenko).`,
    ['виправте логін у рядку «AD -», і автоматизація обробить заявку сама.']],
  no_date: () => ['• Поле «Termination date»: порожнє.\n• Due date: порожня.\n• Дата в темі заявки (РРРР-ММ-ДД): немає.',
    'не вказано дату звільнення, тому невідомо, коли закривати доступи.',
    ['заповніть «Termination date» (РРРР-ММ-ДД); у день звільнення або пізніше автоматизація обробить заявку сама.']],
  bad_date: v => [`• Дата звільнення в заявці: «${v}».`,
    `дату «${v}» не вдалося розпізнати (очікується формат РРРР-ММ-ДД).`,
    ['виправте дату в полі «Termination date», і автоматизація обробить заявку сама.']],
};
const fmt = ([checked, result, next]) =>
  `⚠ Автоматичний offboarding не виконано.\n\nЩо перевірено:\n${checked}\n\nРезультат: ${result}\n\n` +
  `Що робити далі:\n${next.map((s, i) => `${i + 1}. ${s.charAt(0).toUpperCase()}${s.slice(1)}`).join('\n')}\n\n` +
  'Заявку залишено відкритою. Нічого в AD і Google не змінено. Автоматизація перевіряє заявку щодня о 18:00; про ту саму проблему повторно не пише.';

const results = [];
const openIds = new Set();
for (const issue of issues) {
  if (!issue || !issue.tracker || issue.tracker.id !== TRACKER_ID) continue;
  const id = issue.id;
  openIds.add(String(id));
  let L = parseLogin(issue);
  const D = parseDate(issue);

  // Дата в майбутньому: просто чекаємо, нічого не пишемо.
  if (D.date && D.date > today) continue;

  // Логіна немає: шукатимемо в AD за ПІБ (рішення приймає Decide AD Action).
  const N = L.reason === 'no_login' ? parseName(issue) : null;
  if (N) L = { name: N };

  const problem = L.reason ? L : (D.reason ? D : null);
  if (problem) {
    const key = problem.reason + ':' + (problem.value || '');
    if (state.notified_input[id] === key) continue;
    state.notified_input[id] = key;
    results.push({ json: {
      action: 'notify', id, reason: problem.reason, subject: issue.subject || '',
      note: fmt(NOTES[problem.reason](problem.value)),
    } });
    continue;
  }

  delete state.notified_input[id];
  if (L.name) {
    results.push({ json: {
      action: 'process', gw_ok, id, lookup: 'name', login: '', guest_email: '', leaver_date: D.date, subject: issue.subject || '',
      fio: L.name.fio, sn: L.name.sn, gn: L.name.gn, pairs: L.name.pairs,
      tenure_days: tenureOf(issue),
      login_variants: [...new Set(L.name.pairs.flatMap(([g, sn]) => loginVariants(g, sn)))],
      ldap_sn: slots(L.name.pairs.map(p => p[1]), 4),
      ldap_sam: slots(L.name.pairs.flatMap(([g, sn]) => loginVariants(g, sn)), 16),
    } });
    continue;
  }
  const email = L.login.includes('@') ? L.login : `${L.login}@example.com`;
  const sam = email.split('@')[0];
  const guest = email.endsWith('.guest.google') ? email : `${email.replace('@', '_')}@tenant.example.org.guest.google`;
  results.push({ json: {
    action: 'process', gw_ok, id, lookup: 'login', login: sam, guest_email: guest, leaver_date: D.date, subject: issue.subject || '',
    ldap_sn: slots([], 4),
    ldap_sam: slots([sam], 16),
  } });
}

// Забуваємо закриті заявки.
for (const k of Object.keys(state.notified_input)) if (!openIds.has(k)) delete state.notified_input[k];
for (const k of Object.keys(state.notified_run)) if (!openIds.has(k)) delete state.notified_run[k];

return results;

// Що робити з акаунтом в AD за результатом пошуку (по всьому домену).
// lookup = login: пошук за sAMAccountName; lookup = name: за прізвищем, далі звіряємо ім'я (логіна в заявці немає).
// ad_status: disable | already_done | not_found | multiple | outside_scope | fired_but_enabled | name_not_found | name_multiple
const SCOPE = ',OU=AllUsers,OU=COMPANY,DC=example,DC=com';
const FIRED_OU = 'OU=Уволенные,DC=example,DC=com';
const ACCOUNTDISABLE = 2;

const leaver = $('Loop Over Tickets').first().json;
const one = v => Array.isArray(v) ? v[0] : v;
const low = v => String(one(v) || '').toLowerCase();
const endsWithCI = (s, tail) => s.toLowerCase().endsWith(tail.toLowerCase());
let found = $input.all().map(i => i.json).filter(j => j && j.dn);

const where = j => {
  const dn = String(j.dn);
  const uac = parseInt(one(j.userAccountControl), 10) || 0;
  const ou = endsWithCI(dn, ',' + FIRED_OU) ? 'Уволенные' : (dn.match(/,OU=([^,]+)/) || [])[1] || '?';
  return `${one(j.sAMAccountName)} (${ou}, ${(uac & ACCOUNTDISABLE) ? 'заблокований' : 'активний'})`;
};

let out = { ...leaver, ad_status: '', dn: '', target_dn: '', new_uac: '', ad_matches: 0, candidates: '', found_by_name: false, ignored_disabled: '', skipped_tenure: '', tenure_checked: '' };

if (leaver.lookup === 'name') {
  const pairs = leaver.pairs || [[leaver.gn, leaver.sn]];
  const sns = new Set(pairs.map(p => p[1].toLowerCase()));
  const sameSurname = found.filter(j => sns.has(low(j.sn)));
  const byName = found.filter(j => pairs.some(([g, s]) => low(j.givenName) === g.toLowerCase() && low(j.sn) === s.toLowerCase()));
  // Запасний шлях: акаунт із логіном за шаблоном, у якого ім'я/прізвище порожні або збігаються.
  const byLogin = found.filter(j => (leaver.login_variants || []).includes(low(j.sAMAccountName)) &&
    pairs.some(([g, s]) => (!low(j.givenName) || low(j.givenName) === g.toLowerCase()) && (!low(j.sn) || low(j.sn) === s.toLowerCase())));
  let pick = byName.length ? byName : byLogin;
  // Перевірка за датою створення: дата створення акаунта + «Загалом днів співпраці» із заявки = дата звільнення (допуск 3 дні).
  // Так відсіюються однофамільці й старі дублікати (на реальних заявках збіг був рівно 0 днів, дублікати розходились на 30+).
  const createdOf = j => { const m = String(one(j.whenCreated) || '').match(/^(\d{4})(\d{2})(\d{2})/); return m ? `${m[1]}-${m[2]}-${m[3]}` : ''; };
  const fits = j => { const c = createdOf(j); return !!c && Math.abs(Math.round((Date.parse(leaver.leaver_date) - Date.parse(c)) / 86400000) - leaver.tenure_days) <= 3; };
  const withDate = j => `${where(j)}, створено ${createdOf(j) || '?'}`;
  let tenureMismatch = false;
  if (leaver.tenure_days != null && pick.length) {
    const fit = pick.filter(fits);
    if (fit.length === 0) { tenureMismatch = true; out.candidates = pick.map(withDate).join('; '); }
    else if (fit.length === 1) {
      out.skipped_tenure = pick.filter(j => j !== fit[0]).map(withDate).join('; ');
      out.tenure_checked = `створено ${createdOf(fit[0])}, співпраця ${leaver.tenure_days} дн., звільнення ${leaver.leaver_date}`;
      pick = fit;
    } else { out.candidates = fit.map(withDate).join('; '); pick = fit; }
  } else {
    // Терміну співпраці немає: кілька акаунтів з таким іменем, уже заблоковані дублікати ігноруємо, якщо активний рівно один.
    const active = pick.filter(j => !((parseInt(one(j.userAccountControl), 10) || 0) & ACCOUNTDISABLE));
    if (pick.length > 1 && active.length === 1) {
      out.ignored_disabled = pick.filter(j => j !== active[0]).map(where).join('; ');
      pick = active;
    }
  }
  found = pick;
  out.found_by_login_pattern = !byName.length && found.length === 1;
  if (tenureMismatch) {
    out.ad_status = 'name_tenure_mismatch';
    found = [];
  } else if (found.length === 0) {
    out.ad_status = 'name_not_found';
    out.candidates = sameSurname.slice(0, 5).map(j => `${one(j.displayName) || one(j.cn)}: ${where(j)}`).join('; ');
  } else if (found.length > 1) {
    out.ad_status = 'name_multiple';
    out.candidates = out.candidates || found.map(where).join('; ');
  } else {
    out.login = String(one(found[0].sAMAccountName));
    out.guest_email = `${out.login}_example.com@tenant.example.org.guest.google`;
    out.found_by_name = true;
    out.gn = String(one(found[0].givenName) || leaver.gn);  // як записано в AD
    out.sn = String(one(found[0].sn) || leaver.sn);
  }
}

out.ad_matches = found.length;
if (!out.ad_status) {
  if (found.length === 0) out.ad_status = 'not_found';
  else if (found.length > 1) { out.ad_status = 'multiple'; out.candidates = found.map(where).join('; '); }
  else {
    const dn = String(found[0].dn);
    const uac = parseInt(one(found[0].userAccountControl), 10) || 0;
    const disabled = (uac & ACCOUNTDISABLE) === ACCOUNTDISABLE;
    out.dn = dn;
    if (endsWithCI(dn, ',' + FIRED_OU)) {
      out.ad_status = disabled ? 'already_done' : 'fired_but_enabled';
    } else if (endsWithCI(dn, SCOPE)) {
      // RDN до першої неекранованої коми (CN=Petrenko\, Ivan,OU=...).
      const rdn = dn.match(/^((?:\\.|[^,\\])+),/)[1];
      out.ad_status = 'disable';
      out.new_uac = String(uac | ACCOUNTDISABLE);  // інші прапорці акаунта не чіпаємо
      out.target_dn = `${rdn},${FIRED_OU}`;
    } else {
      out.ad_status = 'outside_scope';
    }
  }
}

return [{ json: out, pairedItem: { item: 0 } }];

// Підсумок по заявці після кроку Google: текст звіту і рішення, чи закривати заявку.
// Сюди приходить відповідь Google з двох гілок: видалення гостя (AD заблоковано або вже було) і перевірка гостя (в AD акаунта немає).
// Закриваємо, якщо гостя видалено (2xx) або його не було (404, або 403 при робочому доступі до API). Інакше коментар, заявка відкрита;
// наступного дня AD уже «already_done», тож повториться лише крок Google. Той самий коментар двічі не пишемо.
const d = $('Code: Decide AD Action').first().json;
const r = $input.first().json;
const state = $getWorkflowStaticData('global');
state.notified_run = state.notified_run || {};

const code = Number(r.statusCode || (r.error && (r.error.httpCode || r.error.status)) || 0);
// Для сервісного акаунта «Google service account (guests)» неіснуючий гість дає 403, а не 404 (перевірено 14.10.2026:
// наявний гість 200, вигаданий 403). Тому 403 = «гостя немає», лише якщо на початку запуску доступ до API працював.
const gone = code === 404 || (code === 403 && d.gw_ok === true);
const msg = (r.body && r.body.error && r.body.error.message) || (r.error && (r.error.message || r.error.description)) || r.statusMessage || 'невідома помилка';
const tail = 'Автоматизація перевіряє заявку щодня о 18:00; про ту саму проблему повторно не пише.';
const adminFix = '1. Перевірте права сервісного акаунта Google (User Management Admin) і ключ у кредах n8n «Google service account (guests)».\n';

let out;
if (d.ad_status === 'not_found') {
  // Логін є, в AD акаунта немає. Гостя теж немає: записів ніде немає, імовірно видалено автоматично за неактивність.
  const checkedAd = `• Active Directory: пошук за логіном «${d.login}» по всьому домену, включно з OU «Уволенные»: акаунта немає.`;
  if (gone) {
    delete state.notified_run[d.id];
    out = { id: d.id, close: true, notify: false, login: d.login, guest_email: d.guest_email, leaver_date: d.leaver_date,
      note: 'Автоматичний offboarding: доступів не знайдено, заявку закрито.\n\n' +
            `Що перевірено:\n${checkedAd}\n• Google Workspace: гостьовий акаунт ${d.guest_email}: не існує (Google: ${code}).\n\n` +
            'Висновок: записів про працівника немає ні в AD, ні в Google. Найімовірніше, акаунт було видалено автоматично ' +
            'через тривалу неактивність. Закривати нічого.\n\n' +
            'Архівування: запис додано до архівного реєстру Google Sheets.' };
  } else {
    const exists = code >= 200 && code < 300;
    const key = exists ? 'nf_guest_exists' : 'nf_gw_error:' + code;
    const notify = state.notified_run[d.id] !== key;
    state.notified_run[d.id] = key;
    out = { id: d.id, close: false, notify,
      note: '⚠ Автоматичний offboarding не виконано.\n\n' +
            `Що перевірено:\n${checkedAd}\n• Google Workspace: гостьовий акаунт ${d.guest_email}: ` +
            (exists ? 'існує.' : `перевірити не вдалося (${code || 'немає відповіді'}): ${msg}.`) + '\n\n' +
            (exists
              ? 'Результат: в AD акаунта немає, а гостьовий акаунт у Google є. Так не має бути, тому автоматично нічого не видалено.\n\n' +
                'Що робити далі:\n1. Перевірте, чи правильний логін у рядку «AD -» (можлива помилка в логіні).\n' +
                '2. Якщо логін правильний, видаліть гостьовий акаунт вручну і закрийте заявку.\n\n'
              : 'Результат: не вдалося перевірити Google, тому заявку не закрито.\n\n' +
                `Що робити далі:\n${adminFix}2. Автоматизація повторить перевірку під час наступного запуску.\n\n`) +
            'Заявку залишено відкритою. Нічого в AD і Google не змінено. ' + tail };
  }
} else {
  // AD заблоковано (щойно або раніше), результат видалення гостя.
  let gw, gwOk;
  if (code >= 200 && code < 300) { gw = 'Гостьовий запис видалено з домену.'; gwOk = true; }
  else if (gone) { gw = `Гостьового запису не було (${code}), видаляти нічого.`; gwOk = true; }
  else { gw = `НЕ видалено (${code || 'немає відповіді'}): ${msg}`; gwOk = false; }

  const ad = d.ad_status === 'already_done'
    ? 'Акаунт уже був заблокований і перебуває в OU «Уволенные».'
    : 'Акаунт заблоковано та переміщено в OU «Уволенные».';
  const body =
    `1. Active Directory:\n• Логін: ${d.login}` +
    (d.found_by_name ? ` (у заявці не вказано, знайдено в AD за ПІБ «${d.fio}»: ${d.gn} ${d.sn}, єдиний збіг` +
      (d.found_by_login_pattern ? '; ім’я/прізвище в AD не заповнені, знайдено за шаблоном логіна' : '') +
      (d.tenure_checked ? '; перевірено за датою створення: ' + d.tenure_checked : '') +
      (d.skipped_tenure ? '; інші акаунти з таким іменем пропущені (дата створення не збігається): ' + d.skipped_tenure : '') +
      (d.ignored_disabled ? '; інші акаунти з таким іменем уже заблоковані й пропущені: ' + d.ignored_disabled : '') + ')' : '') +
    `\n• Статус: ${ad}\n` +
    `2. Google Workspace (Guest):\n• Акаунт: ${d.guest_email}\n• Статус: ${gw}\n`;

  if (gwOk) {
    delete state.notified_run[d.id];
    out = { id: d.id, close: true, notify: false, login: d.login, guest_email: d.guest_email, leaver_date: d.leaver_date,
      note: `Автоматичний offboarding успішно завершено.\nЗвіт про закриття доступів:\n${body}` +
            '3. Архівування:\n• Запис додано до архівного реєстру Google Sheets.' };
  } else {
    const key = 'gw_error:' + code;
    const notify = state.notified_run[d.id] !== key;
    state.notified_run[d.id] = key;
    const next = code === 403 || code === 401
      ? adminFix
      : '1. Перевірте гостьовий акаунт у консолі адміністратора Google Workspace і відповідь вище.\n';
    out = { id: d.id, close: false, notify,
      note: `⚠ Автоматичний offboarding завершено частково: AD виконано, Google ні.\n\n${body}\n` +
            `Що робити далі:\n${next}` +
            '2. Нічого не робіть з AD: наступного запуску автоматизація побачить, що акаунт уже заблокований, і повторить лише крок Google.\n' +
            '3. Або видаліть гостя вручну і закрийте заявку.\n\n' +
            'Заявку залишено відкритою. ' + tail };
  }
}
return [{ json: out, pairedItem: { item: 0 } }];

// Коментар у заявку, коли AD-крок неможливий або впав. Заявка лишається відкритою.
// Формат: що перевірено, результат, що робити далі. notify = false, якщо про цю саму проблему вже писали.
const d = $('Code: Decide AD Action').first().json;
const inp = $input.first().json;
const state = $getWorkflowStaticData('global');
state.notified_run = state.notified_run || {};

const err = inp.error ? String(inp.error.message || inp.error.description || inp.error) : '';
const reason = err ? 'ad_error' : d.ad_status;
const guest = d.guest_email || `<логін>_example.com@tenant.example.org.guest.google`;
const byLogin = `• Пошук в AD за логіном (sAMAccountName) «${d.login}» по всьому домену, включно з OU «Уволенные».`;
const variants = (d.pairs || [[d.gn, d.sn]]).map(p => p.join(' ')).join(' / ');
const byName = `• AD-логін у заявці не вказано (рядок «AD -» порожній).\n` +
  `• ПІБ із заявки: «${d.fio}», варіанти латиницею: ${variants}.\n` +
  `• Пошук в AD за прізвищем і звірка імені за кожним варіантом.`;
const closeByHand = `якщо акаунт в AD уже видалено вручну, перевірте, чи немає гостьового акаунта Google (${guest}), і закрийте заявку вручну.`;

const T = {
  not_found: [byLogin, `акаунт «${d.login}» не знайдено в AD.`, [
    'перевірте логін у рядку «AD -» (можлива помилка в логіні); після виправлення автоматизація обробить заявку сама;', closeByHand]],
  multiple: [byLogin, `за логіном «${d.login}» знайдено кілька акаунтів: ${d.candidates}. Потрібна ручна перевірка.`, [
    'визначте, який акаунт належить працівнику, і заблокуйте його вручну;', 'закрийте заявку вручну.']],
  outside_scope: [byLogin, `акаунт знайдено поза OU=AllUsers (${d.dn}). Автоматичне блокування для нього вимкнене, потрібна ручна перевірка.`, [
    'перевірте, чи це той самий працівник (можливо, адмін-персонал або службовий акаунт);',
    'якщо так, заблокуйте його вручну і закрийте заявку; якщо ні, виправте логін у рядку «AD -».']],
  fired_but_enabled: [byLogin, `акаунт уже в OU «Уволенные», але не заблокований (${d.dn}).`, [
    'заблокуйте акаунт вручну (Disable Account);', 'далі автоматизація сама видалить гостьовий акаунт Google і закриє заявку.']],
  name_not_found: [byName, `акаунт в AD не знайдено.` + (d.candidates ? ` З таким прізвищем є: ${d.candidates}.` : ' Людей із таким прізвищем в AD немає.'), [
    'якщо знаєте логін, впишіть його в рядок «AD -», і автоматизація обробить заявку сама;', closeByHand]],
  name_tenure_mismatch: [byName, `акаунт із таким іменем є (${d.candidates}), але дата його створення не збігається з тривалістю співпраці із заявки (${d.tenure_days} дн. до ${d.leaver_date}). Схоже, це інша людина або старий дублікат, автоматично не блокуємо.`, [
    'перевірте, чи це акаунт працівника, і впишіть його логін у рядок «AD -»;', 'якщо акаунт працівника інший, автоматизація обробить заявку після виправлення логіна.']],
  name_multiple: [byName, `знайдено кілька акаунтів з таким іменем і прізвищем: ${d.candidates}. Автоматично обрати не можна.`, [
    'визначте, який акаунт належить працівнику, і впишіть його логін у рядок «AD -»;', 'автоматизація обробить заявку під час наступного запуску.']],
  ad_error: [d.found_by_name ? byName + `\n• Знайдено акаунт: ${d.login} (${d.dn}).` : byLogin + `\n• Знайдено акаунт: ${d.dn}.`,
    `не вдалося заблокувати або перемістити акаунт в AD: ${err}`, [
    'перевірте права сервісного облікового запису n8n в AD (блокування й переміщення в OU «Уволенные») і доступність контролера домену;',
    'автоматизація повторить спробу під час наступного запуску; або виконайте блокування вручну.']],
};
const [checked, result, next] = T[reason] || ['', reason, []];

const key = reason + ':' + (reason === 'ad_error' ? '' : d.dn + '|' + d.candidates);
const notify = state.notified_run[d.id] !== key;
state.notified_run[d.id] = key;

return [{ json: {
  id: d.id, close: false, reason, notify,
  note: `⚠ Автоматичний offboarding не виконано.\n\nЩо перевірено:\n${checked}\n\nРезультат: ${result}\n\n` +
        `Що робити далі:\n${next.map((s, i) => `${i + 1}. ${s.charAt(0).toUpperCase()}${s.slice(1)}`).join('\n')}\n\n` +
        'Заявку залишено відкритою. ' + (reason === 'ad_error' ? 'Google не змінено; стан акаунта в AD перевірте вручну (блокування могло пройти без переміщення). ' : 'Нічого в AD і Google не змінено. ') + 'Автоматизація перевіряє заявку щодня о 18:00; про ту саму проблему повторно не пише.',
}, pairedItem: { item: 0 } }];
